198	/**
199	 * The claims kept on a sheet, newest first. A claim without a date takes the sheet's today; a
200	 * missing note is stored empty. Only a DRAFT claim can be edited (409); an open claim is changed by
201	 * voiding it and adding a new one. No claim dated in a closed period can be added, edited or change
202	 * status (423). A claim's due-by is fixed when it is added: its date plus the terms of its person's
203	 * grade in force on that date (the sheet's terms for a grade without its own); later changes to the
204	 * terms or the claim's date leave it as fixed. No claim dated after its person's retirement date can be added or edited (422).
205	 * A claim with a negative amount is a correction: it must name, by number, a SETTLED claim of the
206	 * same person, or it is refused (422); a claim that is not a correction names none.
207	 */
208	@Service
209	public class ClaimService {
210	
211	    private final ClaimRepository claims;
212	    private final ClaimSequenceRepository sequences;
213	    private final PersonRepository people;
214	    private final PeriodRepository periods;
215	    private final RateService rates;
216	    private final RoleService roles;
217	    private final SheetService sheets;
218	    private final Audit audit;
