220	    public ClaimService(ClaimRepository claims, ClaimSequenceRepository sequences, PersonRepository people, PeriodRepository periods, RateService rates,
221	            RoleService roles, SheetService sheets, Audit audit) {
222	        this.roles = roles;
223	        this.claims = claims;
224	        this.sequences = sequences;
225	        this.people = people;
226	        this.periods = periods;
227	        this.rates = rates;
228	        this.sheets = sheets;
229	        this.audit = audit;
