237	    @Transactional
238	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
239	            String corrects) {
240	        sheets.load(sheetId, user);
241	        // Lock the sheet, so a period closed at the same moment is seen.
242	        Sheet sheet = sheets.lock(sheetId).orElseThrow();
243	        Person person = people.findByIdAndSheetId(personId, sheetId)
244	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
245	        LocalDate on = date != null ? date : sheets.today(sheetId);
246	        refuseIfClosed(sheetId, on);
247	        refuseIfRetired(person, on);
248	        String corrected = correctedNumber(sheetId, personId, amount, corrects);
249	        Claim claim = claims.save(new Claim(sheetId, personId, scaled(amount), on, note != null ? note : "", corrected,
250	                sheet.dueBy(person.gradeOn(on), on)));
251	        record("CLAIM_ADDED", user, person, claim);
252	        return claim;
253	    }
254	
255	    @Transactional
256	    public Claim update(String sheetId, String user, Long claimId, BigDecimal amount, LocalDate date, String note,
257	            String corrects) {
258	        sheets.lock(sheetId);
259	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
260	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
261	        LocalDate on = date != null ? date : sheets.today(sheetId);
262	        if (claim.getStatus() != ClaimStatus.DRAFT) {
263	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be edited");
264	        }
265	        refuseIfClosed(sheetId, claim.getDate());
266	        refuseIfClosed(sheetId, on);
267	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
268	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
269	        refuseIfRetired(person, on);
270	        String corrected = correctedNumber(sheetId, person.getId(), amount, corrects);
271	        claim.setAmount(scaled(amount));
272	        claim.setCorrects(corrected);
273	        claim.setDate(on);
274	        claim.setNote(note != null ? note : "");
275	        record("CLAIM_EDITED", user, person, claim);
276	        return claim;
277	    }
278	
279	    /**
280	     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
281	     * gives the claim the sheet's next number, or its number within its period while the sheet numbers
282	     * by period (see {@link #takeNumber}); a voided claim keeps it (the number is never given again).
283	     * Opening records who opened it; that user cannot settle it (403).
284	     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to
285	     * the sheet's floor, with its late charge added if it is overdue; later floor and late percent changes
286	     * leave it as fixed. Every rounding is half up for a claim dated before the sheet's policy date and
287	     * half to even otherwise; later policy date changes leave it as fixed too. A correction's due is its amount times that rate, rounded the same way, with no
288	     * floor and no late charge. A clerk
289	     * settling a claim whose due is above the sheet's clerk limit, if it has one, makes it PENDING instead
290	     * (CLAIM_PENDING), its due left live until a steward approves it; a claim with no due (no rate) is
291	     * refused (403), as it cannot be shown to be within the limit. A steward settles any claim.
292	     */
293	    @Transactional
294	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
295	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
296	        // and a period closed at the same moment is seen.
297	        Sheet sheet = sheets.lock(sheetId)
298	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
299	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
300	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
301	        refuseIfClosed(sheetId, claim.getDate());
302	        if (!claim.getStatus().canBecome(next)) {
303	            throw new ResponseStatusException(HttpStatus.CONFLICT,
304	                    "A " + claim.getStatus() + " claim cannot become " + next);
305	        }
306	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
307	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
308	        }
309	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
310	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
311	        String number = next == ClaimStatus.OPEN ? takeNumber(sheet, claim.getDate()) : claim.getNumber();
312	        List<String> extra = new ArrayList<>();
313	        BigDecimal due = null;
314	        if (next == ClaimStatus.SETTLED) {
315	            due = dueNow(sheet, person, claim);
316	            if (overClerkLimit(sheet, user, due)) {
317	                next = ClaimStatus.PENDING;
318	            } else {
319	                extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
320	            }
321	        }
322	        claim.setStatus(next);
323	        claim.setNumber(number);
324	        if (next == ClaimStatus.OPEN) {
325	            claim.setOpenedBy(user);
326	        }
327	        if (next == ClaimStatus.SETTLED) {
328	            claim.setSettledDue(due);
329	        }
330	        record(switch (next) {
331	            case OPEN -> "CLAIM_OPENED";
332	            case PENDING -> "CLAIM_PENDING";
333	            case SETTLED -> "CLAIM_SETTLED";
334	            case VOID -> "CLAIM_VOIDED";
335	            case DRAFT -> throw new IllegalStateException();
336	        }, user, person, claim, number, extra);
337	        return claim;
338	    }
339	
340	    /**
341	     * A steward approves a PENDING claim: it becomes SETTLED, its due fixed at that moment as settling
342	     * fixes it (CLAIM_APPROVED due=&lt;due&gt;). Only a PENDING claim can be approved (409), only by a
343	     * steward, and not by the user who opened it (403).
344	     */
345	    @Transactional
346	    public Claim approve(String sheetId, String user, Long claimId) {
347	        Sheet sheet = sheets.lock(sheetId)
348	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
349	        Claim claim = pending(sheetId, user, claimId);
350	        if (user.equals(claim.getOpenedBy())) {
351	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
352	        }
353	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
354	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
355	        BigDecimal due = dueNow(sheet, person, claim);
356	        claim.setStatus(ClaimStatus.SETTLED);
357	        claim.setSettledDue(due);
358	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(),
359	                List.of("due=" + (due == null ? "n/a" : due.toPlainString())));
360	        return claim;
361	    }
362	
363	    /**
364	     * A steward rejects a PENDING claim with a reason: it goes back to OPEN (CLAIM_REJECTED
365	     * reason=&lt;reason&gt;). Only a PENDING claim can be rejected (409), only by a steward (403).
366	     */
367	    @Transactional
368	    public Claim reject(String sheetId, String user, Long claimId, String reason) {
369	        sheets.lock(sheetId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
370	        Claim claim = pending(sheetId, user, claimId);
371	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
372	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
373	        claim.setStatus(ClaimStatus.OPEN);
374	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), List.of("reason=" + reason));
375	        return claim;
376	    }
377	
378	    /**
379	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its number
380	     * and date, and its due follows its new person's grade (CLAIM_REASSIGNED, naming the new person, with
381	     * from=&lt;old name&gt; to=&lt;new name&gt;). Only a steward can move a claim (403); a SETTLED or VOID claim
382	     * cannot move, nor can a claim move to the person it is already on (409); a correction cannot move, as
383	     * it corrects a claim of its own person, nor can a claim move to a person retired before its date (422).
384	     */
385	    @Transactional
386	    public Claim reassign(String sheetId, String user, Long claimId, Long toPersonId) {
387	        sheets.lock(sheetId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
388	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
389	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
390	        refuseIfClosed(sheetId, claim.getDate());
391	        if (roles.of(sheetId, user) != Role.STEWARD) {
392	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reassign a claim");
393	        }
394	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
395	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be reassigned");
396	        }
397	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
398	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
399	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
400	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
401	        if (to.getId().equals(from.getId())) {
402	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already on " + to.getName());
403	        }
404	        if (claim.isCorrection()) {
405	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
406	                    "A correction corrects a claim of its own person, so it cannot be reassigned");
407	        }
408	        refuseIfRetired(to, claim.getDate());
409	        claim.setPersonId(to.getId());
410	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
411	                List.of("from=" + from.getName(), "to=" + to.getName()));
412	        return claim;
413	    }
