415	    /** The PENDING claim a steward approves or rejects; refused otherwise (409, 403, 423). */
416	    private Claim pending(String sheetId, String user, Long claimId) {
417	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
418	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
419	        refuseIfClosed(sheetId, claim.getDate());
420	        if (claim.getStatus() != ClaimStatus.PENDING) {
421	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim is not pending");
422	        }
423	        if (roles.of(sheetId, user) != Role.STEWARD) {
424	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim");
425	        }
426	        return claim;
427	    }
