429	    /** The claim's due if it were settled now; null when its grade has no rate on its date. */
430	    private BigDecimal dueNow(Sheet sheet, Person person, Claim claim) {
431	        return sheet.liveDue(rates.inForce(sheet.getId(), person.gradeOn(claim.getDate()), claim.getDate())
432	                .map(rate -> sheet.dueAt(claim.getAmount(), rate.getRate(), claim.getDate()))
433	                .orElse(null), claim.getDate(), claim.getDueBy(), claim.isCorrection());
434	    }
