436	    /** How many of the selected claims a bulk open opened, and how many it refused. */
437	    public record BulkResult(int opened, int refused) {
438	    }
439	
440	    /**
441	     * Open the selected claims together, numbering them in list order: the people in the order they
442	     * were added, and within a person the newest claim (by date) first, claims of the same date in
443	     * the order they were added. A selected claim that cannot be opened (or is not on the sheet) is
444	     * refused and left as it is; the others are still opened.
445	     */
446	    @Transactional
447	    public BulkResult bulkOpen(String sheetId, String user, List<Long> claimIds) {
448	        sheets.lock(sheetId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet"));
449	        Set<Long> selected = new HashSet<>(claimIds);
450	        Map<Long, Integer> personOrder = new HashMap<>();
451	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
452	        for (int i = 0; i < listed.size(); i++) {
453	            personOrder.put(listed.get(i).getId(), i);
454	        }
455	        List<Claim> ordered = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
456	                .filter(claim -> selected.contains(claim.getId()))
457	                .sorted(Comparator.<Claim>comparingInt(claim -> personOrder.getOrDefault(claim.getPersonId(), Integer.MAX_VALUE))
458	                        .thenComparing(Claim::getDate, Comparator.reverseOrder())
459	                        .thenComparing(Claim::getId))
460	                .toList();
461	        int opened = 0;
462	        for (Claim claim : ordered) {
463	            try {
464	                changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN);
465	                opened++;
466	            } catch (ResponseStatusException refused) {
467	                // Left as it is.
468	            }
469	        }
470	        return new BulkResult(opened, selected.size() - opened);
471	    }
472	
473	    /**
474	     * The number a claim corrects: for a negative amount, the number of a SETTLED claim of the same
475	     * person, refused (422) when none is named or it names no such claim; none for any other amount.
476	     */
477	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
478	        if (amount.signum() >= 0) {
479	            return null;
480	        }
481	        boolean settled = corrects != null && claims.findFirstBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
482	                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED)
483	                .isPresent();
484	        if (!settled) {
485	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
486	                    "A negative amount must correct a settled claim of the same person");
487	        }
488	        return corrects;
489	    }
490	
491	    /**
492	     * The number a claim opened now is given: while the sheet numbers by period (its today on or after
493	     * its period numbering from), the next in the sequence of the period the claim's date is in,
494	     * &lt;period name&gt;-&lt;n&gt;, or X-&lt;n&gt; for a claim in no period; otherwise the sheet's next number.
495	     * The caller holds the sheet's lock.
496	     */
497	    private String takeNumber(Sheet sheet, LocalDate date) {
498	        if (!sheet.numbersByPeriod()) {
499	            return String.valueOf(sheet.takeClaimNumber());
500	        }
501	        String prefix = periods.findBySheetIdOrderByFromAsc(sheet.getId()).stream()
502	                .filter(period -> period.contains(date))
503	                .map(Period::getName)
504	                .findFirst()
505	                .orElse("X");
506	        ClaimSequence sequence = sequences.findById(new ClaimSequence.Key(sheet.getId(), prefix))
507	                .orElseGet(() -> sequences.save(new ClaimSequence(sheet.getId(), prefix)));
508	        return sequence.take();
509	    }
510	
511	    /**
512	     * Whether a clerk settling a claim of this due is above the sheet's clerk limit, so it goes PENDING;
513	     * refused (403) when the claim has no due, as it cannot be shown to be within the limit.
514	     */
515	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
516	        BigDecimal limit = sheet.getClerkLimit();
517	        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
518	            return false;
519	        }
520	        if (due == null) {
521	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
522	                    "A clerk cannot settle a claim with no due while there is a clerk limit");
523	        }
524	        return due.compareTo(limit) > 0;
525	    }
526	
527	    /** Refuse (423) a change to a claim dated in a closed period. */
528	    private void refuseIfClosed(String sheetId, LocalDate date) {
529	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
530	                .filter(period -> period.isClosed() && period.contains(date))
531	                .findFirst()
532	                .ifPresent(period -> {
533	                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
534	                });
535	    }
536	
537	    /** Refuse (422) a claim dated after its person's retirement date. */
538	    private static void refuseIfRetired(Person person, LocalDate date) {
539	        if (person.retiredOn(date)) {
540	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
541	                    person.getName() + " is retired from " + person.getRetiredFrom());
542	        }
543	    }
544	
545	    private void record(String event, String user, Person person, Claim claim) {
546	        record(event, user, person, claim, claim.getNumber(), List.of());
547	    }
548	
549	    /**
550	     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
551	     */
552	    private void record(String event, String user, Person person, Claim claim, String number, List<String> extra) {
553	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
554	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
555	        if (number != null) {
556	            fields.add("number=" + number);
557	        }
558	        fields.addAll(extra);
559	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
560	    }
561	
562	    private static BigDecimal scaled(BigDecimal amount) {
563	        return amount.setScale(2, RoundingMode.UNNECESSARY);
564	    }
565	}
