749	/**
750	 * A claim's status. It starts as DRAFT, can be opened and then settled; a DRAFT or OPEN claim can
751	 * be voided. A clerk settling a claim whose due is above the clerk limit makes it PENDING instead:
752	 * a steward then approves it (SETTLED) or rejects it (back to OPEN). SETTLED and VOID are final.
753	 * Only OPEN, PENDING and SETTLED claims count toward the totals, a PENDING one as an open one.
754	 */
755	public enum ClaimStatus {
756	    DRAFT, OPEN, PENDING, SETTLED, VOID;
757	
758	    /** Whether a claim in this status counts toward the totals. */
759	    public boolean counts() {
760	        return this == OPEN || this == PENDING || this == SETTLED;
761	    }
762	
763	    /** Whether a claim in this status counts as open: OPEN or PENDING. */
764	    public boolean isOpen() {
765	        return this == OPEN || this == PENDING;
766	    }
767	
768	    /**
769	     * Whether a claim in this status may be opened, settled or voided into the given one. Approving
770	     * and rejecting a PENDING claim are their own changes.
771	     */
772	    public boolean canBecome(ClaimStatus next) {
773	        return switch (next) {
774	            case OPEN -> this == DRAFT;
775	            case PENDING, SETTLED -> this == OPEN;
776	            case VOID -> this == DRAFT || this == OPEN;
777	            case DRAFT -> false;
778	        };
779	    }
780	}
